// Display names and icons for items, and names for storage places.

import itemTable from "../data/itemTable.json";
import buildingNames from "../data/buildingNames.json";
import type { Storage } from "../types";

/** game item id -> [Korean name, icon file]; generated by scripts/build_item_table.py */
const ITEMS: Record<string, string[]> = itemTable;

/** building id -> Korean name; generated by scripts/build_dex.py from the structure icons */
const BUILDING_NAMES: Record<string, string> = buildingNames;
const BUILDING_NAMES_LOWER = new Map(Object.entries(BUILDING_NAMES).map(([k, v]) => [k.toLowerCase(), v]));
export const buildingName = (id: string): string => BUILDING_NAMES[id] ?? BUILDING_NAMES_LOWER.get(id.toLowerCase()) ?? id;

export const itemName = (id: string): string => ITEMS[id]?.[0] ?? id;

/** Whether the search text matches the item's name or id. */
export const matchesItem = (id: string, query: string): boolean =>
  !query || itemName(id).includes(query) || id.toLowerCase().includes(query.toLowerCase());

/**
 * Items matching the search that are not in `have`, sorted by name. Items without a Korean name
 * (old ids the game no longer names) are left out.
 */
export function missingItems(query: string, have: Set<string>): string[] {
  if (!query) return [];
  return Object.keys(ITEMS)
    .filter((id) => !have.has(id) && ITEMS[id][0] !== id && matchesItem(id, query))
    .sort((a, b) => itemName(a).localeCompare(itemName(b), "ko"));
}

/** URL of the item icon, or null when the item has none */
export function itemIconUrl(id: string): string | null {
  const icon = ITEMS[id]?.[1];
  return icon ? `/icons/items/${icon}` : null;
}

export interface Place {
  key: string;
  name: string;
  storages: Storage[];
}

/**
 * Groups a base's storages into named places: one place per building (same buildings
 * numbered by position) and one place for everything dropped on the ground.
 */
export function placesOf(storages: Storage[]): Place[] {
  const places: Place[] = [];
  const dropped: Storage[] = [];
  const byBuilding = new Map<string, Storage[]>();
  let inventory: Storage | null = null;
  for (const s of storages) {
    if (s.kind === "pickup") continue;
    if (s.kind === "inventory") {
      inventory = s;
      continue;
    }
    if (s.kind === "dropped") {
      dropped.push(s);
      continue;
    }
    const key = s.kind === "guildStorage" ? "guildStorage" : (s.buildObjectId ?? s.kind);
    byBuilding.set(key, [...(byBuilding.get(key) ?? []), s]);
  }
  for (const [key, list] of byBuilding) {
    const base = key === "guildStorage" ? "길드 창고" : buildingName(key);
    // stable numbering: west to east, then north to south
    list.sort((a, b) => (a.location?.x ?? 0) - (b.location?.x ?? 0) || (a.location?.y ?? 0) - (b.location?.y ?? 0));
    // a name given in game wins; otherwise the building name, numbered when there are several
    list.forEach((s, i) => places.push({ key: s.containerId, name: s.customName || (list.length > 1 ? `${base} ${i + 1}` : base), storages: [s] }));
  }
  if (dropped.length) places.push({ key: "dropped", name: "바닥 (버린 아이템)", storages: dropped });
  if (inventory) places.unshift({ key: "inventory", name: "내 인벤토리", storages: [inventory] });
  return places;
}
